+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContact() {
+        navigate(ContactView.class);
+        name = find(TextField.class).withLabel("Name").single();
+        email = find(EmailField.class).withLabel("Email").single();
+        phone = find(TextField.class).withLabel("Phone").single();
+        message = find(TextArea.class).withLabel("Message").single();
+        send = find(Button.class).withText("Send").single();
+    }
+
+    @Test
+    void validatesEmptyAndMalformedInputsWithoutSending() {
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+        assertEquals(0, test(find(Grid.class).single()).size());
+        assertTrue(send.isEnabled());
+
+        test(name).setValue("Ada");
+        test(email).setValue("broken");
+        test(phone).setValue("123");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertFalse(name.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals("broken", email.getValue());
+        assertEquals(501, message.getValue().length());
+        assertEquals(0, test(find(Grid.class).single()).size());
+    }
+
+    @Test
+    void sendsByClickAndEnterAndRetainsNewestFirstAcrossVisits() {
+        test(name).setValue("Ada");
+        test(phone).setValue("123");
+        test(message).setValue("First message");
+        test(send).click();
+        assertFalse(send.isEnabled());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        assertTrue(find(Notification.class).exists());
+        test(email).setValue("ada@example.com");
+        assertTrue(send.isEnabled());
+        test(name).setValue("Grace");
+        test(message).setValue("x".repeat(500));
+        fireShortcut(Key.ENTER);
+        assertFalse(send.isEnabled());
+        var grid = test(find(Grid.class).single());
+        assertEquals(2, grid.size());
+        assertEquals("Grace", grid.getCellText(0, 0));
+        assertEquals("Ada", grid.getCellText(1, 0));
+        test(find(RouterLink.class).withText("About").single()).click();
+        assertEquals("About", find(H1.class).single().getText());
+        assertFalse(find(Dialog.class).exists());
+        navigate(ContactView.class);
+        assertEquals(2, test(find(Grid.class).single()).size());
+        assertTrue(find(Button.class).withText("Send").single().isEnabled());
+    }
+
+    @Test
+    void confirmsBothLinkAndProgrammaticNavigationAndKeepsDraft() {
+        test(message).setValue("Draft");
+        test(find(RouterLink.class).single()).click();
+        assertTrue(find(Dialog.class).single().isOpened());
+        test(find(Button.class).withText("Keep editing").single()).click();
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("Draft", message.getValue());
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue(find(Dialog.class).single().isOpened());
+        test(find(Button.class).withText("Discard").single()).click();
+        assertEquals("About", find(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertTrue(find(TextArea.class).single().isEmpty());
+        assertEquals(0, test(find(Grid.class).single()).size());
+    }
+}
